-- Plan « Triathlon longue distance (70.3 et Ironman) en aéro » (12 semaines) : 45 séances,
-- objectif aéro et indicateur de réussite (passages en TT validés) par séance.
-- Textes en 9 langues assemblés depuis des gabarits par type. Rejouable.

WITH tpl(typ, lang, name, obj, info) AS (VALUES

('e_cont', 'fr', 'Endurance TT {n}×{d}', 'Objectif physiologique : Développer l''endurance fondamentale et la base aérobie. Objectif aéro : Tenir la position TT en endurance (65-72 % FTP), sans se relever pendant les blocs.', 'Endurance fondamentale en position TT : intensité facile pour que toute l''attention aille à la tenue (tête basse, épaules relâchées, appui stable). Les blocs s''allongent d''une semaine à l''autre.'),
('e_cont', 'en', 'TT endurance {n}×{d}', 'Physiological goal: Build base endurance and your aerobic base. Aero goal: Hold the TT position at endurance pace (65-72% FTP) without sitting up during the blocks.', 'Base endurance in the TT position: easy intensity so all your attention goes to holding it (head low, shoulders relaxed, stable support). The blocks get longer every week.'),
('e_cont', 'es', 'Resistencia TT {n}×{d}', 'Objetivo fisiológico: Desarrollar la resistencia básica y la base aeróbica. Objetivo aero: Mantener la posición TT a ritmo de resistencia (65-72 % FTP) sin incorporarte en los bloques.', 'Resistencia básica en posición TT: intensidad suave para que toda la atención vaya a mantenerla (cabeza baja, hombros relajados, apoyo estable). Los bloques se alargan cada semana.'),
('e_cont', 'it', 'Resistenza TT {n}×{d}', 'Obiettivo fisiologico: Sviluppare la resistenza di base e la base aerobica. Obiettivo aero: Tenere la posizione TT a ritmo di resistenza (65-72 % FTP) senza rialzarti nei blocchi.', 'Resistenza di base in posizione TT: intensità facile perché l''attenzione vada tutta alla tenuta (testa bassa, spalle rilassate, appoggio stabile). I blocchi si allungano ogni settimana.'),
('e_cont', 'de', 'TT-Ausdauer {n}×{d}', 'Physiologisches Ziel: Grundlagenausdauer und aerobe Basis entwickeln. Aero-Ziel: Die TT-Position im Grundlagentempo (65-72 % FTP) halten, ohne dich in den Blöcken aufzurichten.', 'Grundlagenausdauer in TT-Position: leichte Intensität, damit die ganze Aufmerksamkeit dem Halten gilt (Kopf tief, Schultern locker, stabile Auflage). Die Blöcke werden jede Woche länger.'),
('e_cont', 'nl', 'TT-duur {n}×{d}', 'Fysiologisch doel: Basisduur en je aerobe basis ontwikkelen. Aerodoel: De TT-houding vasthouden op duurtempo (65-72 % FTP) zonder overeind te komen tijdens de blokken.', 'Basisduur in TT-houding: lichte intensiteit zodat al je aandacht naar het vasthouden gaat (hoofd laag, schouders ontspannen, stabiele steun). De blokken worden elke week langer.'),
('e_cont', 'pt', 'Resistência TT {n}×{d}', 'Objetivo fisiológico: Desenvolver a resistência de base e a base aeróbia. Objetivo aero: Manter a posição TT em ritmo de resistência (65-72 % FTP) sem levantar o tronco nos blocos.', 'Resistência de base na posição TT: intensidade leve para que toda a atenção vá para mantê-la (cabeça baixa, ombros relaxados, apoio estável). Os blocos ficam mais longos a cada semana.'),
('e_cont', 'ja', 'TT持久 {n}×{d}', '生理学的目標：基礎持久力と有酸素ベースを伸ばす。 エアロ目標：持久ペース（65〜72 % FTP）でTTポジションを保ち、ブロック中は起き上がらない。', 'TTポジションでの基礎持久力：強度は楽にして保つことに集中（頭を低く、肩の力を抜き、安定した支え）。ブロックは週ごとに長くなります。'),
('e_cont', 'tr', 'TT dayanıklılık {n}×{d}', 'Fizyolojik hedef: Temel dayanıklılığı ve aerobik temeli geliştirmek. Aero hedefi: Dayanıklılık temposunda (%65-72 FTP) TT pozisyonunu koru, bloklarda doğrulma.', 'TT pozisyonunda temel dayanıklılık: tüm dikkatin pozisyonu korumakta olsun diye kolay yoğunluk (baş aşağıda, omuzlar gevşek, sabit destek). Bloklar her hafta uzar.'),
('e_long', 'fr', 'Fond TT {m}''', 'Objectif physiologique : Développer la base aérobie et la résistance à la fatigue sur la durée. Objectif aéro : Accumuler le plus long temps en TT de la semaine à 70-72 % FTP.', 'Sortie longue : de longs blocs en TT entrecoupés de courtes pauses redressées. Cherche une position que tu peux tenir, pas la plus basse.'),
('e_long', 'en', 'Long TT ride {m}''', 'Physiological goal: Build your aerobic base and fatigue resistance over time. Aero goal: Build up the longest TT time of the week at 70-72% FTP.', 'Long ride: long TT blocks broken up by short upright breaks. Find a position you can hold, not the lowest one.'),
('e_long', 'es', 'Fondo TT {m}''', 'Objetivo fisiológico: Desarrollar la base aeróbica y la resistencia a la fatiga en la duración. Objetivo aero: Acumular el mayor tiempo en TT de la semana al 70-72 % FTP.', 'Salida larga: bloques largos en TT con pausas cortas erguido. Busca una posición que puedas mantener, no la más baja.'),
('e_long', 'it', 'Fondo TT {m}''', 'Obiettivo fisiologico: Sviluppare la base aerobica e la resistenza alla fatica sulla durata. Obiettivo aero: Accumulare il tempo in TT più lungo della settimana al 70-72 % FTP.', 'Uscita lunga: lunghi blocchi in TT con brevi pause eretto. Cerca una posizione che puoi tenere, non la più bassa.'),
('e_long', 'de', 'Lange TT-Fahrt {m}''', 'Physiologisches Ziel: Aerobe Basis und Ermüdungsresistenz über die Dauer entwickeln. Aero-Ziel: Die längste TT-Zeit der Woche bei 70-72 % FTP sammeln.', 'Lange Fahrt: lange TT-Blöcke mit kurzen aufrechten Pausen. Such eine Position, die du halten kannst, nicht die tiefste.'),
('e_long', 'nl', 'Lange TT-rit {m}''', 'Fysiologisch doel: Je aerobe basis en weerstand tegen vermoeidheid over de duur ontwikkelen. Aerodoel: De langste TT-tijd van de week opbouwen op 70-72 % FTP.', 'Lange rit: lange TT-blokken met korte pauzes rechtop. Zoek een houding die je kunt volhouden, niet de laagste.'),
('e_long', 'pt', 'Fundo TT {m}''', 'Objetivo fisiológico: Desenvolver a base aeróbia e a resistência à fadiga na duração. Objetivo aero: Acumular o maior tempo em TT da semana a 70-72 % FTP.', 'Treino longo: blocos longos em TT com pausas curtas ereto. Procure uma posição que consiga manter, não a mais baixa.'),
('e_long', 'ja', 'ロングTT {m}''', '生理学的目標：有酸素ベースと長時間の疲労耐性を伸ばす。 エアロ目標：70〜72 % FTPで週で最も長いTT時間を積み上げる。', 'ロングライド：短いアップライト休憩を挟んだ長いTTブロック。一番低い姿勢ではなく、維持できる姿勢を探して。'),
('e_long', 'tr', 'Uzun TT sürüş {m}''', 'Fizyolojik hedef: Aerobik temeli ve uzun sürede yorgunluğa direnci geliştirmek. Aero hedefi: %70-72 FTP''de haftanın en uzun TT süresini biriktir.', 'Uzun sürüş: kısa dik molalarla bölünmüş uzun TT blokları. En alçak değil, koruyabileceğin bir pozisyon bul.'),
('e_tempo', 'fr', 'Tempo TT {n}×{d}', 'Objectif physiologique : Développer l''endurance musculaire au tempo. Objectif aéro : Tenir la position TT au tempo (80-85 % FTP), quand la respiration s''accélère.', 'Le tempo est l''allure d''un CLM long ou d''un triathlon longue distance : assez dur pour que le haut du corps veuille se relever. Récupère redressé entre les blocs.'),
('e_tempo', 'en', 'TT tempo {n}×{d}', 'Physiological goal: Build muscular endurance at tempo. Aero goal: Hold the TT position at tempo (80-85% FTP), when breathing gets faster.', 'Tempo is the pace of a long TT or a long-distance triathlon: hard enough that your upper body wants to sit up. Recover upright between blocks.'),
('e_tempo', 'es', 'Tempo TT {n}×{d}', 'Objetivo fisiológico: Desarrollar la resistencia muscular a tempo. Objetivo aero: Mantener la posición TT a tempo (80-85 % FTP), cuando la respiración se acelera.', 'El tempo es el ritmo de una CRI larga o de un triatlón de larga distancia: lo bastante duro para que el tronco quiera incorporarse. Recupera erguido entre bloques.'),
('e_tempo', 'it', 'Tempo TT {n}×{d}', 'Obiettivo fisiologico: Sviluppare la resistenza muscolare a ritmo tempo. Obiettivo aero: Tenere la posizione TT a ritmo tempo (80-85 % FTP), quando il respiro accelera.', 'Il tempo è il ritmo di una crono lunga o di un triathlon lungo: abbastanza duro da voler rialzare il busto. Recupera eretto tra i blocchi.'),
('e_tempo', 'de', 'TT-Tempo {n}×{d}', 'Physiologisches Ziel: Kraftausdauer im Tempobereich entwickeln. Aero-Ziel: Die TT-Position im Tempobereich (80-85 % FTP) halten, wenn die Atmung schneller wird.', 'Tempo ist das Tempo eines langen Zeitfahrens oder einer Langdistanz: hart genug, dass sich der Oberkörper aufrichten will. Zwischen den Blöcken aufrecht erholen.'),
('e_tempo', 'nl', 'TT-tempo {n}×{d}', 'Fysiologisch doel: Spieruithouding op tempo ontwikkelen. Aerodoel: De TT-houding vasthouden op tempo (80-85 % FTP), als de ademhaling versnelt.', 'Tempo is het tempo van een lange tijdrit of lange-afstandstriatlon: zwaar genoeg dat je bovenlijf overeind wil. Herstel rechtop tussen de blokken.'),
('e_tempo', 'pt', 'Tempo TT {n}×{d}', 'Objetivo fisiológico: Desenvolver a resistência muscular em ritmo tempo. Objetivo aero: Manter a posição TT em ritmo tempo (80-85 % FTP), quando a respiração acelera.', 'O tempo é o ritmo de um contrarrelógio longo ou de um triatlo de longa distância: duro o bastante para o tronco querer levantar. Recupere ereto entre os blocos.'),
('e_tempo', 'ja', 'TTテンポ {n}×{d}', '生理学的目標：テンポで筋持久力を伸ばす。 エアロ目標：呼吸が速くなるテンポ（80〜85 % FTP）でTTポジションを保つ。', 'テンポはロングTTやロングディスタンス・トライアスロンのペース。上体を起こしたくなる強さです。ブロックの間は起き上がって回復。'),
('e_tempo', 'tr', 'TT tempo {n}×{d}', 'Fizyolojik hedef: Tempoda kas dayanıklılığını geliştirmek. Aero hedefi: Nefes hızlandığında tempoda (%80-85 FTP) TT pozisyonunu koru.', 'Tempo, uzun bir zamana karşı yarışın ya da uzun mesafe triatlonun temposudur: üst gövdenin doğrulmak isteyeceği kadar zor. Bloklar arasında dik toparlan.'),
('r_tri', 'fr', 'Allure triathlon TT {n}×{d}', 'Objectif physiologique : Développer l''endurance au seuil aérobie haut, l''allure du vélo en triathlon. Objectif aéro : Tenir la position TT à l''allure triathlon (85-90 % FTP) sur des blocs longs, sans se relever pour soulager la nuque.', 'L''allure du vélo d''un triathlon M ou d''un 70.3 : assez dure pour fatiguer la nuque et le dos, assez longue pour que la position décide du résultat. Récupère redressé entre les blocs. Échauffement seuil (15'') : montée progressive, 3'' au tempo puis 3 accélérations de 20'''' à 120 % FTP pour ouvrir les jambes avant le premier bloc.'),
('r_tri', 'en', 'Triathlon pace TT {n}×{d}', 'Physiological goal: Build endurance at high aerobic intensity, the triathlon bike pace. Aero goal: Hold the TT position at triathlon pace (85-90% FTP) over long blocks, without sitting up to relieve your neck.', 'The bike pace of an Olympic-distance or 70.3 triathlon: hard enough to tire your neck and back, long enough for the position to decide the result. Recover upright between blocks. Threshold warm-up (15''): progressive build, 3'' at tempo, then 3 × 20'''' surges at 120% FTP to open the legs before the first block.'),
('r_tri', 'es', 'Ritmo triatlón TT {n}×{d}', 'Objetivo fisiológico: Desarrollar la resistencia a intensidad aeróbica alta, el ritmo de la bici en triatlón. Objetivo aero: Mantener la posición TT a ritmo de triatlón (85-90 % FTP) en bloques largos, sin incorporarte para aliviar el cuello.', 'El ritmo de bici de un triatlón olímpico o un 70.3: lo bastante duro para cansar cuello y espalda, lo bastante largo para que la posición decida el resultado. Recupera erguido entre bloques. Calentamiento de umbral (15''): subida progresiva, 3'' a tempo y 3 aceleraciones de 20'''' al 120 % FTP para abrir las piernas antes del primer bloque.'),
('r_tri', 'it', 'Ritmo triathlon TT {n}×{d}', 'Obiettivo fisiologico: Sviluppare la resistenza ad alta intensità aerobica, il ritmo bici del triathlon. Obiettivo aero: Tenere la posizione TT al ritmo triathlon (85-90 % FTP) su blocchi lunghi, senza rialzarti per sgravare il collo.', 'Il ritmo bici di un triathlon olimpico o di un 70.3: abbastanza duro da stancare collo e schiena, abbastanza lungo perché la posizione decida il risultato. Recupera eretto tra i blocchi. Riscaldamento soglia (15''): salita progressiva, 3'' a ritmo tempo poi 3 accelerazioni di 20'''' al 120 % FTP per aprire le gambe prima del primo blocco.'),
('r_tri', 'de', 'Triathlontempo TT {n}×{d}', 'Physiologisches Ziel: Ausdauer bei hoher aerober Intensität entwickeln, dem Radtempo im Triathlon. Aero-Ziel: Die TT-Position im Triathlontempo (85-90 % FTP) über lange Blöcke halten, ohne dich zur Entlastung des Nackens aufzurichten.', 'Das Radtempo einer olympischen Distanz oder eines 70.3: hart genug, um Nacken und Rücken zu ermüden, lang genug, dass die Position über das Ergebnis entscheidet. Zwischen den Blöcken aufrecht erholen. Schwellen-Aufwärmen (15''): progressiver Aufbau, 3'' im Tempo, dann 3 Antritte à 20'''' bei 120 % FTP, um die Beine vor dem ersten Block zu öffnen.'),
('r_tri', 'nl', 'Triatlontempo TT {n}×{d}', 'Fysiologisch doel: Uithouding op hoge aerobe intensiteit ontwikkelen, het fietstempo in triatlon. Aerodoel: De TT-houding op triatlontempo (85-90 % FTP) over lange blokken vasthouden, zonder overeind te komen om je nek te ontlasten.', 'Het fietstempo van een olympische triatlon of een 70.3: zwaar genoeg om nek en rug te vermoeien, lang genoeg om de houding het resultaat te laten bepalen. Herstel rechtop tussen de blokken. Drempel-warming-up (15''): geleidelijke opbouw, 3'' op tempo en dan 3 versnellingen van 20'''' op 120 % FTP om de benen te openen voor het eerste blok.'),
('r_tri', 'pt', 'Ritmo triatlo TT {n}×{d}', 'Objetivo fisiológico: Desenvolver a resistência em alta intensidade aeróbia, o ritmo da bike no triatlo. Objetivo aero: Manter a posição TT no ritmo do triatlo (85-90 % FTP) em blocos longos, sem levantar para aliviar o pescoço.', 'O ritmo de bike de um triatlo olímpico ou de um 70.3: duro o bastante para cansar pescoço e costas, longo o bastante para a posição decidir o resultado. Recupere ereto entre os blocos. Aquecimento de limiar (15''): subida progressiva, 3'' em ritmo tempo e depois 3 acelerações de 20'''' a 120 % FTP para abrir as pernas antes do primeiro bloco.'),
('r_tri', 'ja', 'トライアスロンペース TT {n}×{d}', '生理学的目標：高い有酸素強度（トライアスロンのバイクペース）での持久力を伸ばす。 エアロ目標：長いブロックでトライアスロンペース（85〜90 % FTP）のTTを保ち、首を楽にするために起き上がらない。', 'オリンピックディスタンスや70.3のバイクペース：首と背中が疲れる強さ、ポジションが結果を左右する長さ。ブロックの間は起き上がって回復。 閾値ウォームアップ（15分）：徐々に上げ、テンポで3分、最初のブロック前に脚を開くため120 % FTPで20秒の加速を3本。'),
('r_tri', 'tr', 'Triatlon temposu TT {n}×{d}', 'Fizyolojik hedef: Yüksek aerobik yoğunlukta, triatlon bisiklet temposunda dayanıklılığı geliştirmek. Aero hedefi: Uzun bloklarda triatlon temposunda (%85-90 FTP) TT pozisyonunu koru, enseyi rahatlatmak için doğrulma.', 'Olimpik mesafe ya da 70.3 triatlonun bisiklet temposu: enseyi ve sırtı yoracak kadar zor, sonucu pozisyonun belirleyeceği kadar uzun. Bloklar arasında dik toparlan. Eşik ısınması (15''): kademeli artış, tempoda 3'', ardından ilk bloktan önce bacakları açmak için %120 FTP''de 3 × 20'''' hızlanma.'),
('t_ss', 'fr', 'Sweet spot TT {n}×{d}', 'Objectif physiologique : Faire monter la FTP avec une fatigue mesurée. Objectif aéro : Tenir la position TT à 88-92 % FTP sur des blocs longs.', 'Le sweet spot développe la FTP avec une fatigue mesurée. En TT, c''est l''allure d''un CLM de 40 km à 1 h : la position doit tenir sous l''effort. Échauffement seuil (15'') : montée progressive, 3'' au tempo puis 3 accélérations de 20'''' à 120 % FTP pour ouvrir les jambes avant le premier bloc.'),
('t_ss', 'en', 'TT sweet spot {n}×{d}', 'Physiological goal: Raise your FTP with moderate fatigue. Aero goal: Hold the TT position at 88-92% FTP over long blocks.', 'Sweet spot builds FTP with moderate fatigue. In TT, it''s the pace of a 40 km TT or a 1 h effort: the position must hold under effort. Threshold warm-up (15''): progressive build, 3'' at tempo, then 3 × 20'''' surges at 120% FTP to open the legs before the first block.'),
('t_ss', 'es', 'Sweet spot TT {n}×{d}', 'Objetivo fisiológico: Subir la FTP con una fatiga moderada. Objetivo aero: Mantener la posición TT al 88-92 % FTP en bloques largos.', 'El sweet spot desarrolla la FTP con una fatiga moderada. En TT es el ritmo de una CRI de 40 km o de 1 h: la posición debe aguantar con el esfuerzo. Calentamiento de umbral (15''): subida progresiva, 3'' a tempo y 3 aceleraciones de 20'''' al 120 % FTP para abrir las piernas antes del primer bloque.'),
('t_ss', 'it', 'Sweet spot TT {n}×{d}', 'Obiettivo fisiologico: Alzare la FTP con una fatica misurata. Obiettivo aero: Tenere la posizione TT all''88-92 % FTP su blocchi lunghi.', 'Lo sweet spot sviluppa la FTP con una fatica misurata. In TT è il ritmo di una crono di 40 km o di 1 h: la posizione deve tenere sotto sforzo. Riscaldamento soglia (15''): salita progressiva, 3'' a ritmo tempo poi 3 accelerazioni di 20'''' al 120 % FTP per aprire le gambe prima del primo blocco.'),
('t_ss', 'de', 'TT-Sweet-Spot {n}×{d}', 'Physiologisches Ziel: Die FTP bei moderater Ermüdung steigern. Aero-Ziel: Die TT-Position bei 88-92 % FTP über lange Blöcke halten.', 'Sweet Spot entwickelt die FTP bei moderater Ermüdung. In TT ist es das Tempo eines 40-km-Zeitfahrens oder einer Stunde: Die Position muss unter Belastung halten. Schwellen-Aufwärmen (15''): progressiver Aufbau, 3'' im Tempo, dann 3 Antritte à 20'''' bei 120 % FTP, um die Beine vor dem ersten Block zu öffnen.'),
('t_ss', 'nl', 'TT-sweetspot {n}×{d}', 'Fysiologisch doel: Je FTP verhogen met beperkte vermoeidheid. Aerodoel: De TT-houding vasthouden op 88-92 % FTP over lange blokken.', 'Sweet spot ontwikkelt de FTP met beperkte vermoeidheid. In TT is het het tempo van een tijdrit van 40 km of 1 uur: de houding moet standhouden onder inspanning. Drempel-warming-up (15''): geleidelijke opbouw, 3'' op tempo en dan 3 versnellingen van 20'''' op 120 % FTP om de benen te openen voor het eerste blok.'),
('t_ss', 'pt', 'Sweet spot TT {n}×{d}', 'Objetivo fisiológico: Aumentar a FTP com fadiga moderada. Objetivo aero: Manter a posição TT a 88-92 % FTP em blocos longos.', 'O sweet spot desenvolve a FTP com fadiga moderada. Em TT, é o ritmo de um contrarrelógio de 40 km ou de 1 h: a posição tem de aguentar sob esforço. Aquecimento de limiar (15''): subida progressiva, 3'' em ritmo tempo e depois 3 acelerações de 20'''' a 120 % FTP para abrir as pernas antes do primeiro bloco.'),
('t_ss', 'ja', 'TTスイートスポット {n}×{d}', '生理学的目標：疲労を抑えてFTPを高める。 エアロ目標：長いブロックで88〜92 % FTPのTTポジションを保つ。', 'スイートスポットは疲労を抑えつつFTPを伸ばします。TTでは40 km TTや1時間の努力のペース：負荷の下でも姿勢を保つこと。 閾値ウォームアップ（15分）：徐々に上げ、テンポで3分、最初のブロック前に脚を開くため120 % FTPで20秒の加速を3本。'),
('t_ss', 'tr', 'TT sweet spot {n}×{d}', 'Fizyolojik hedef: Ölçülü yorgunlukla FTP''yi yükseltmek. Aero hedefi: Uzun bloklarda %88-92 FTP''de TT pozisyonunu koru.', 'Sweet spot, ölçülü yorgunlukla FTP''yi geliştirir. TT''de 40 km''lik zamana karşı ya da 1 saatlik efor temposudur: pozisyon efor altında dayanmalı. Eşik ısınması (15''): kademeli artış, tempoda 3'', ardından ilk bloktan önce bacakları açmak için %120 FTP''de 3 × 20'''' hızlanma.'),
('v_44', 'fr', 'PMA {n}×{d} + TT', 'Objectif physiologique : Développer la PMA (VO2max). Objectif aéro : Rester en position TT pendant chaque récupération de PMA et sur le bloc final à 70 % FTP, souffle court compris.', 'Intervalles longs de PMA (format 4×4'' de Helgerud) en position libre ; chaque récupération et le bloc final à 70 % FTP se font en TT, pour apprendre à rester bas quand le souffle est court. Échauffement PMA (16'') : montée progressive, 3'' à 90 % FTP pour lancer le système aérobie, 3 × 30'''' à 120 % FTP puis 3'' faciles avant les intervalles.'),
('v_44', 'en', 'VO2max {n}×{d} + TT', 'Physiological goal: Build your VO2max. Aero goal: Stay in the TT position during every VO2max recovery and the final block at 70% FTP, even when out of breath.', 'Long VO2max intervals (Helgerud''s 4×4'' format) in any position; every recovery and the final block at 70% FTP are in TT, to learn to stay low when you''re out of breath. VO2max warm-up (16''): progressive build, 3'' at 90% FTP to kick-start the aerobic system, 3 × 30'''' at 120% FTP, then 3'' easy before the intervals.'),
('v_44', 'es', 'VO2max {n}×{d} + TT', 'Objetivo fisiológico: Desarrollar el VO2max. Objetivo aero: Mantener la posición TT en cada recuperación de VO2max y en el bloque final al 70 % FTP, aun sin aliento.', 'Intervalos largos de VO2max (formato 4×4'' de Helgerud) en posición libre; cada recuperación y el bloque final al 70 % FTP se hacen en TT, para aprender a seguir abajo sin aliento. Calentamiento de VO2max (16''): subida progresiva, 3'' al 90 % FTP para activar el sistema aeróbico, 3 × 30'''' al 120 % FTP y 3'' suaves antes de los intervalos.'),
('v_44', 'it', 'VO2max {n}×{d} + TT', 'Obiettivo fisiologico: Sviluppare il VO2max. Obiettivo aero: Restare in posizione TT in ogni recupero di VO2max e nel blocco finale al 70 % FTP, anche col fiato corto.', 'Intervalli lunghi di VO2max (formato 4×4'' di Helgerud) in posizione libera; ogni recupero e il blocco finale al 70 % FTP si fanno in TT, per imparare a restare bassi col fiato corto. Riscaldamento VO2max (16''): salita progressiva, 3'' al 90 % FTP per attivare il sistema aerobico, 3 × 30'''' al 120 % FTP poi 3'' facili prima degli intervalli.'),
('v_44', 'de', 'VO2max {n}×{d} + TT', 'Physiologisches Ziel: Die VO2max entwickeln. Aero-Ziel: In jeder VO2max-Erholung und im Schlussblock bei 70 % FTP in TT-Position bleiben, auch wenn die Luft knapp ist.', 'Lange VO2max-Intervalle (4×4''-Format nach Helgerud) in freier Position; jede Erholung und der Schlussblock bei 70 % FTP in TT, um tief zu bleiben, wenn die Luft knapp ist. VO2max-Aufwärmen (16''): progressiver Aufbau, 3'' bei 90 % FTP, um das aerobe System anzuwerfen, 3 × 30'''' bei 120 % FTP, dann 3'' locker vor den Intervallen.'),
('v_44', 'nl', 'VO2max {n}×{d} + TT', 'Fysiologisch doel: Je VO2max ontwikkelen. Aerodoel: In TT-houding blijven tijdens elk VO2max-herstel en het slotblok op 70 % FTP, ook als je adem tekortkomt.', 'Lange VO2max-intervallen (4×4''-formaat van Helgerud) in vrije houding; elk herstel en het slotblok op 70 % FTP in TT, om laag te leren blijven als je adem tekortkomt. VO2max-warming-up (16''): geleidelijke opbouw, 3'' op 90 % FTP om het aerobe systeem op gang te brengen, 3 × 30'''' op 120 % FTP en dan 3'' rustig voor de intervallen.'),
('v_44', 'pt', 'VO2max {n}×{d} + TT', 'Objetivo fisiológico: Desenvolver o VO2max. Objetivo aero: Ficar na posição TT em cada recuperação de VO2max e no bloco final a 70 % FTP, mesmo sem fôlego.', 'Intervalos longos de VO2max (formato 4×4'' de Helgerud) em posição livre; cada recuperação e o bloco final a 70 % FTP são em TT, para aprender a ficar baixo sem fôlego. Aquecimento de VO2max (16''): subida progressiva, 3'' a 90 % FTP para ativar o sistema aeróbio, 3 × 30'''' a 120 % FTP e 3'' leves antes dos intervalos.'),
('v_44', 'ja', 'VO2max {n}×{d} + TT', '生理学的目標：VO2maxを伸ばす。 エアロ目標：息が苦しくても、VO2maxの回復と最後の70 % FTPブロックではTTポジションを保つ。', 'ロングVO2maxインターバル（Helgerudの4×4''形式）をポジション自由で。回復と最後の70 % FTPブロックはTTで、息が苦しいときも低く保つ練習。 VO2maxウォームアップ（16分）：徐々に上げ、有酸素系を起動するため90 % FTPで3分、120 % FTPで30秒×3、インターバル前に楽に3分。'),
('v_44', 'tr', 'VO2max {n}×{d} + TT', 'Fizyolojik hedef: VO2max''ı geliştirmek. Aero hedefi: Nefesin kesik olsa da her VO2max toparlanmasında ve %70 FTP''deki son blokta TT pozisyonunda kal.', 'Serbest pozisyonda uzun VO2max intervalleri (Helgerud 4×4'' formatı); her toparlanma ve %70 FTP''deki son blok TT''de, nefes kesikken alçakta kalmayı öğrenmek için. VO2max ısınması (16''): kademeli artış, aerobik sistemi başlatmak için %90 FTP''de 3'', %120 FTP''de 3 × 30'''', ardından intervallerden önce 3'' kolay.')
), wk(lang, p) AS (VALUES ('fr', 'S'), ('en', 'W'), ('es', 'S'), ('it', 'S'), ('de', 'W'), ('nl', 'W'), ('pt', 'S'), ('ja', 'W'), ('tr', 'H')
), ind(lang, many, one) AS (VALUES ('fr', 'Réussite : {k} passages en TT validés (≥ 95 % du passage en TT, aucune sortie de 20 s ou plus).', 'Réussite : 1 passage en TT validé (≥ 95 % du passage en TT, aucune sortie de 20 s ou plus).'), ('en', 'Success: {k} TT blocks validated (≥ 95% of the block in TT, no exit of 20 s or more).', 'Success: 1 TT block validated (≥ 95% of the block in TT, no exit of 20 s or more).'), ('es', 'Éxito: {k} tramos en TT validados (≥ 95 % del tramo en TT, ninguna salida de 20 s o más).', 'Éxito: 1 tramo en TT validado (≥ 95 % del tramo en TT, ninguna salida de 20 s o más).'), ('it', 'Riuscita: {k} tratti in TT validati (≥ 95 % del tratto in TT, nessuna uscita di 20 s o più).', 'Riuscita: 1 tratto in TT validato (≥ 95 % del tratto in TT, nessuna uscita di 20 s o più).'), ('de', 'Erfolg: {k} TT-Abschnitte bestanden (≥ 95 % des Abschnitts in TT, kein Verlassen von 20 s oder mehr).', 'Erfolg: 1 TT-Abschnitt bestanden (≥ 95 % des Abschnitts in TT, kein Verlassen von 20 s oder mehr).'), ('nl', 'Geslaagd: {k} TT-stukken gehaald (≥ 95 % van het stuk in TT, geen uitstap van 20 s of langer).', 'Geslaagd: 1 TT-stuk gehaald (≥ 95 % van het stuk in TT, geen uitstap van 20 s of langer).'), ('pt', 'Sucesso: {k} trechos em TT validados (≥ 95 % do trecho em TT, nenhuma saída de 20 s ou mais).', 'Sucesso: 1 trecho em TT validado (≥ 95 % do trecho em TT, nenhuma saída de 20 s ou mais).'), ('ja', '達成条件：TTブロック{k}本を達成（ブロックの95 %以上をTTで、20秒以上の離脱なし）。', '達成条件：TTブロック1本を達成（ブロックの95 %以上をTTで、20秒以上の離脱なし）。'), ('tr', 'Başarı: {k} TT bölümü onaylandı (bölümün ≥ %95''i TT''de, 20 sn veya daha uzun çıkış yok).', 'Başarı: 1 TT bölümü onaylandı (bölümün ≥ %95''i TT''de, 20 sn veya daha uzun çıkış yok).')
), s(skey, typ, week, n, d, minutes, k, aero, blocks, lc) AS (VALUES

